create temporary table h3_ten_days(day date primary key,title text,qids jsonb,minutes int,summaries jsonb) on commit drop;
insert into h3_ten_days values ('2026-09-12'::date,'福州原卷｜第1、2题','["QH3FZ26_Q01", "QH3FZ26_Q02"]'::jsonb,20,'["材料类别与元素用途的事实判断，信息量少，先建立正确的物质分类。", "在粒子数计算中识别气体条件、溶液体积及σ键数，难点是多个常见前提的逐项检查。"]'::jsonb),('2026-09-13'::date,'福州原卷｜第3、4题','["QH3FZ26_Q03", "QH3FZ26_Q04"]'::jsonb,20,'["依次检查芳香族官能团、命名、反应类型和共面性，结构关系可直接从路线辨认。", "由结构和电荷推断元素，再比较电负性、第一电离能、氢键与杂化；比前题多一步元素推断和周期律例外。"]'::jsonb),('2026-09-14'::date,'福州原卷｜第7题','["QH3FZ26_Q07"]'::jsonb,12,'["从催化氧化实验中控制变量，并正确解释“达到同一现象所需鼓气次数”的反向指标；无需长计算，先于复杂流程。"]'::jsonb),('2026-09-15'::date,'福州原卷｜第5、6题','["QH3FZ26_Q05", "QH3FZ26_Q06"]'::jsonb,20,'["区分反应焓变与各步活化能，比较吸附态中间体；要求读懂多步能量图而非仅看最高点。", "连贯追踪钒的价态、两相转移、反萃平衡和受热分解产物，流程信息与氧化还原判断交叉。"]'::jsonb),('2026-09-16'::date,'福州原卷｜第9题','["QH3FZ26_Q09"]'::jsonb,12,'["把有机官能团的氧化数变化与碱性电极反应、极性及产氢量连接，需要完成多步电子守恒。"]'::jsonb),('2026-09-17'::date,'福州原卷｜第8题','["QH3FZ26_Q08"]'::jsonb,12,'["既要排除酸性硝酸根的实验干扰，又要用沉淀平衡解释氧化还原方向，涉及条件变化下的耦合平衡。"]'::jsonb),('2026-09-18'::date,'福州原卷｜第10题','["QH3FZ26_Q10"]'::jsonb,12,'["NH4HCO3滴定同时涉及NH4+和HCO3−的平衡、常数比较、物料/电荷守恒及沉淀影响，综合推理最多。"]'::jsonb);
create temporary table h3_ten_revisions(id text primary key,revision text) on commit drop;
insert into h3_ten_revisions values ('QH3FZ26_Q01','6068527b8d4880f6b48fcf7e8a65f74fcb9bf7ac6992f788f062edcff44a1160'),('QH3FZ26_Q02','66bb73e5ecb478933cf45f8dc62cebca3fb6df1d6a3c70be7d2121148c94f827'),('QH3FZ26_Q03','326b0140e639d30b297c82515c5143523838b51f49747e6f8cce72c8bc78ef12'),('QH3FZ26_Q04','7f30bd32e241a49c03180bfe952eb6ffba61669d1091977fa99226d54a34feea'),('QH3FZ26_Q07','a56dfe663a921be0980d40029ec0c6f3a12b80801966f0d74b43fb7f58ec1ea4'),('QH3FZ26_Q05','22e1adc2fc9c40e570103a015846a4c8c3e8a972000613b59492b1a672328057'),('QH3FZ26_Q06','21a471da5d2ef744c766aca3d0bb82607386878a85164a3b3661afe5c1ef5f92'),('QH3FZ26_Q09','e3fc3f03e0595a0ec055a43be72d8ad6c3bfbf19a14d55cf9d4a220f72d37d37'),('QH3FZ26_Q08','16e786b83faa0c5e2c569e2048c5f0f26ffa47aa291d9222ae6da1090768ab15'),('QH3FZ26_Q10','a560845857366bdc13cbda72ea5816213c18e07c81ddc478c869d8783b8a3732');
do $$
begin
  if (now() at time zone 'Asia/Shanghai')::date >= date '2026-09-12' then raise exception 'Future-only reorder window has closed'; end if;
  perform 1 from public.chem_students_v2 s join h3_ten_students x on x.id=s.id for update of s;
  perform 1 from public.chem_learning_plans p join h3_ten_students x on x.id=p.student_id where p.plan_date between '2026-09-12' and '2026-09-18' for update of p;
  if (select count(*) from public.chem_students_v2 s join h3_ten_students x on x.id=s.id where s.grade_band='高三' and s.record_status='active' and s.metadata->'reviewProgram'=x.old_program) <> 5 then raise exception 'Student/program snapshot changed'; end if;
  if (select count(*) from public.chem_learning_plans p join h3_ten_students x on x.id=p.student_id where p.plan_date between '2026-09-12' and '2026-09-18' and p.mode='REVIEW') <> 35 then raise exception 'Expected exactly 35 existing review plans'; end if;
  if exists(select 1 from public.chem_learning_attempts a join public.chem_learning_plans p on p.id=a.plan_day_id join h3_ten_students s on s.id=p.student_id where p.plan_date between '2026-09-12' and '2026-09-18') or exists(select 1 from app_private.chem_question_answer_locks l join public.chem_learning_plans p on p.id=l.plan_day_id join h3_ten_students s on s.id=p.student_id where p.plan_date between '2026-09-12' and '2026-09-18') then raise exception 'A first answer or attempt now exists; preserve the answered day and re-review scheduling'; end if;
  if (select count(*) from public.chem_questions q join h3_ten_revisions v on v.id=q.id join app_private.chem_question_source_releases r on r.id=q.source_release_id where q.question_revision_token=v.revision and q.grade_band='高三' and q.review_status='approved' and q.scope_status='IN' and q.usable_for_review and r.status='active') <> 10 then raise exception 'Original ten identity/revision/eligibility changed'; end if;
end $$;
-- Change only the question assignment field; keep participation, materials, allowed skills and all other metadata.
update public.chem_students_v2 s set metadata=jsonb_set(s.metadata,'{reviewProgram,questionAssignments}',(select jsonb_object_agg(to_char(day,'YYYY-MM-DD'),qids) from h3_ten_days),false) from h3_ten_students x where s.id=x.id;
update public.chem_learning_plans p set title=d.title,question_count=jsonb_array_length(d.qids),estimated_minutes=d.minutes,knowledge_summaries=array(select jsonb_array_elements_text(d.summaries)),skill_ids=(select array_agg(distinct q.skill_id order by q.skill_id) from public.chem_questions q where q.id in(select jsonb_array_elements_text(d.qids))),target_concept_keys=(select array_agg(distinct q.concept_key order by q.concept_key) from public.chem_questions q where q.id in(select jsonb_array_elements_text(d.qids))) from h3_ten_days d,h3_ten_students s where p.student_id=s.id and p.plan_date=d.day and p.mode='REVIEW';
-- Existing plan IDs, mode, delivery mode, round limit, max level and source identities are retained.
do $$
begin
 if (select count(*) from public.chem_learning_plans p join h3_ten_students s on s.id=p.student_id join h3_ten_days d on d.day=p.plan_date where p.question_count=jsonb_array_length(d.qids) and p.title=d.title)<>35 then raise exception '35-day update verification failed';end if;
 if (select sum(p.question_count) from public.chem_learning_plans p join h3_ten_students s on s.id=p.student_id join h3_ten_days d on d.day=p.plan_date)<>50 then raise exception 'Expected five students times ten original questions';end if;
end $$;
select s.display_name,p.id,p.plan_date,p.title,p.question_count,s.metadata->'reviewProgram'->'questionAssignments'->to_char(p.plan_date,'YYYY-MM-DD') as question_ids from public.chem_students_v2 s join h3_ten_students x on x.id=s.id join public.chem_learning_plans p on p.student_id=s.id join h3_ten_days d on d.day=p.plan_date order by s.display_name,p.plan_date;
commit;
